    "5.3.1.3": { m: "Aile üyeleri ve mesleklerle ilgili içeriği anlamlandırabilme", b: [["a", "Mevcut içerikle ilgili ön tahminlerini kontrol eder."], ["b", "Mevcut içeriğin bileşenlerini bütün içinde konumlandırır."], ["c", "Mevcut içerikte temel ve basit sınıflandırmaları yapar."], ["ç", "Mevcut içerikle ilgili temel ve basit karşılaştırmalar yapar."], ["d", "Mevcut içerikteki somut/basit/temel yatay ve dikey ilişkileri tanır."], ["e", "Mevcut içeriği bireysel olarak içselleştirir."]] },
