    "5.3.2.2": { m: "Aile üyeleri ve mesleklerle ilgili bilgileri bir araya getirebilme", b: [["a", "Destekleyici görseller yardımıyla mevcut içeriğin konusu hakkında basit tahminlerde bulunur."], ["b", "Mevcut içeriğin konusunu genel olarak algılar."], ["c", "Mevcut içerikteki basit ve temel ayrıntıları fark eder."]] },
