    "6.2.5.2": { m: "Okul, okulun bölümleri ve okulda bulunan eşyalarla ilgili ifadelerin kullanıldığı konuşma modelini taklit edebilme", b: [["a", "Tekrarlar ve taklit yoluyla model/örnek içeriğe aşina olur."]] },
    "6.2.5.3": { m: "Okul, okulun bölümleri ve okulda bulunan eşyalarla ilgili ifadelerin kullanıldığı konuşma modelini taklit ederek sözlü içerik oluşturabilme", b: [["a", "Hazırlıklı/hazırlıksız konuşma durumları için model/örnek içeriği taklit ederek yeni içerik tasarlar."], ["b", "Hazırlıklı/hazırlıksız konuşma durumları için model/örnek içeriği taklit ederek yeni içeriği düzenler."]] },
