    "7.1.5.3": { m: "Günlük hayatla ilgili ifadelerin kullanıldığı konuşma modelini taklit ederek sözlü içerik oluşturabilme", b: [["a", "Hazırlıklı/hazırlıksız konuşma durumları için model/örnek içeriği taklit ederek yeni içerik tasarlar."], ["b", "Hazırlıklı/hazırlıksız konuşma durumları için model/örnek içeriği taklit ederek yeni içeriği düzenler."]] },
