    "8.4.1.3": { m: "Mezuniyet ve sonrasındaki süreçle ilgili içeriği anlamlandırabilme", b: [["a", "Mevcut içerikle ilgili ön tahminlerini kontrol eder."], ["b", "Mevcut içeriğin bileşenlerini bütün içinde konumlandırır."], ["c", "Mevcut içerikte temel ve basit sınıflandırmaları yapar."], ["ç", "Mevcut içerikle ilgili temel ve basit karşılaştırmalar yapar."], ["d", "Mevcut içerikteki somut/basit/temel yatay ve dikey ilişkileri tanır."], ["e", "Mevcut içeriği bireysel olarak içselleştirir."]] },
    "8.4.1.4": { m: "Dönem boyunca dinleme/izleme-anlamlandırma becerisi sürecinde duygularını, edindiği bilgi, deneyim ve düşüncelerini bireysel ve etkileşimli biçimde yansıtabilme", b: [["a", "Mevcut içerik ve dinleme/izleme-anlamlandırma sürecine ilişkin gözden geçirdiği bilgi, deneyim, düşünce ve duyguları hakkında basit kişisel aktarımlar yapar."], ["b", "Mevcut içerik ve dinleme/izleme-anlamlandırma sürecine ilişkin gözden geçirdiği bilgi, deneyim, düşünce ve duyguları paylaşarak karşılıklı basit aktarımlar yapar."]] },
    "8.4.2.1": { m: "Mezuniyet ve sonrasındaki süreçle ilgili içeriği okumaya hazırlık yapabilme", b: [["a", "Önceki bilgi ve deneyimleri harekete geçirir."], ["b", "Önceki bilgi ve deneyimler ile mevcut içeriğe ilişkin ipuçları arasındaki temel ilişkileri fark eder."], ["c", "Mevcut içeriğin konusu hakkında basit tahminlerde bulunur."]] },
    "8.4.2.2": { m: "Mezuniyet ve sonrasındaki süreçle ilgili bilgileri bir araya getirebilme", b: [["a", "Destekleyici görseller yardımıyla mevcut içeriğin konusu hakkında basit tahminlerde bulunur."], ["b", "Mevcut içeriğin konusunu genel olarak algılar."], ["c", "Mevcut içerikteki basit ve temel ayrıntıları fark eder."]] },
